q = json.loads((W / "review-aid/review-queue.json").read_text())
entries = []
for it in q["sources"][0]["items"]:
    if it["kind"] != "unresolved_diagnostic":
        continue
    e = dict(it["adjudication_entry"])
    pg, chk = e["page"], e["check"]
    if chk == "missing_lines":
        e["reason"] = ML[pg] + COMMON
    else:
        which = "First parser (same tokens in both parsers unless stated). " if chk == "number_differences" else "Independent (pypdf) parser. "
        e["reason"] = which + ND[pg]
    entries.append(e)
(D / "adjudications.json").write_text(json.dumps({"schema_version": 1, "entries": entries}, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(len(entries), "adjudication entries written")
